class Command(BaseCommand):
    help = "SWOT/TOWS واقعی کسب‌وکار گارانتی خودرو را بارگذاری می‌کند."

    def handle(self, *args, **options):
        bu = BusinessUnit.objects.filter(name=BU_NAME).first()
        if not bu:
            self.stdout.write(self.style.ERROR(f"کسب‌وکار «{BU_NAME}» پیدا نشد؛ رد شد."))
            return

        SWOTItem.objects.filter(business_unit=bu).delete()
        TOWSStrategy.objects.filter(business_unit=bu).delete()

        code_map = {}
        for cat, django_cat in [("S", "s"), ("W", "w"), ("O", "o"), ("T", "t")]:
            for order, text in enumerate(DATA[cat], start=1):
                item = SWOTItem.objects.create(
                    category=django_cat, text=text, weight=3, impact="med", business_unit=bu,
                )
                code_map[f"{cat}{order}"] = item

        total_tows = 0
        for cat, django_cat in [("SO", "so"), ("ST", "st"), ("WO", "wo"), ("WT", "wt")]:
            for order, (text, refs) in enumerate(DATA[cat], start=1):
                strat = TOWSStrategy.objects.create(
                    category=django_cat, text=text, order=order, business_unit=bu,
                )
                source_objs = [code_map[r] for r in refs if r in code_map]
                if source_objs:
                    strat.source_items.set(source_objs)
                total_tows += 1

        self.stdout.write(self.style.SUCCESS(
            f"«{BU_NAME}»: {len(code_map)} مورد SWOT و {total_tows} راهبرد TOWS بارگذاری شد."
        ))
